import{_ as t,o,c as a,a3 as r}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Troubleshooting","description":"ShipperDog troubleshooting - the top ten support scenarios as symptom, cause, and fix, from CLI exit codes and portal 404s to SSO, SCIM, webhooks, gates, and promotion blockers.","frontmatter":{"description":"ShipperDog troubleshooting - the top ten support scenarios as symptom, cause, and fix, from CLI exit codes and portal 404s to SSO, SCIM, webhooks, gates, and promotion blockers."},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md"}'),d={name:"reference/troubleshooting.md"};function i(s,e,n,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>The ten scenarios support actually sees, each as symptom, likely cause, and fix. Codes you meet along the way are explained in <a href="/shipperdog/snapshot/reference/error-codes">error codes</a>; the vocabulary lives in the <a href="/shipperdog/snapshot/reference/glossary">glossary</a>.</p><h2 id="the-cli-exited-non-zero" tabindex="-1">The CLI exited non-zero <a class="header-anchor" href="#the-cli-exited-non-zero" aria-label="Permalink to &quot;The CLI exited non-zero&quot;">​</a></h2><p>The exit code is a stable contract pipelines branch on — read it first, then the printed problem.</p><table tabindex="0"><thead><tr><th>Exit</th><th>What it says</th><th>Fix</th></tr></thead><tbody><tr><td><code>1</code></td><td>Server-side/5xx failure</td><td>Retry; if it repeats, report the trace id.</td></tr><tr><td><code>2</code></td><td>Usage — bad flags, missing args, unresolvable name</td><td>Check the command shape against <a href="/shipperdog/snapshot/how-to/automation/cli-reference">the CLI reference</a>.</td></tr><tr><td><code>3</code></td><td>Auth — no credentials, or 401</td><td>Mint a fresh PAT; <code>shipperdog login</code> or set <code>SHIPPERDOG_TOKEN</code>.</td></tr><tr><td><code>4</code></td><td>Validation — the API refused the request (4xx), or validation settled FAILED</td><td>Read the problem&#39;s code in <a href="/shipperdog/snapshot/reference/error-codes#cli-and-ci">error codes</a>.</td></tr><tr><td><code>5</code></td><td>Network — refused, DNS, timeout</td><td>Check the API URL (<code>--api</code> / <code>SHIPPERDOG_API</code>) and connectivity.</td></tr></tbody></table><h2 id="the-portal-signed-me-out-and-401s-everything" tabindex="-1">The portal signed me out and 401s everything <a class="header-anchor" href="#the-portal-signed-me-out-and-401s-everything" aria-label="Permalink to &quot;The portal signed me out and 401s everything&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Working session turns to <code>UNAUTHENTICATED</code>/<code>INVALID_TOKEN</code> on every action</td><td>The access token expired or was revoked mid-session</td><td>Sign in again; the portal keeps your place. If it repeats immediately, ask your admin whether your account was suspended or the session&#39;s refresh family was revoked (for example by an IdP-initiated logout).</td></tr></tbody></table><h2 id="a-404-for-something-you-know-exists" tabindex="-1">A 404 for something you know exists <a class="header-anchor" href="#a-404-for-something-you-know-exists" aria-label="Permalink to &quot;A 404 for something you know exists&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>An app, version, release, or feedback row 404s for you but not a colleague</td><td>Concealment, not absence: without membership/grant/role you receive the byte-identical 404 a genuine miss produces</td><td>Verify your <a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenant membership</a> and <a href="/shipperdog/snapshot/concepts/authorization">grant</a>; the resource&#39;s owner or an admin can compare in the <a href="/shipperdog/snapshot/how-to/console/siem-streams">audit trail</a></td></tr><tr><td>A release detail 404s right after creation in CI</td><td>Wrong application scope in the CLI reference (<code>--app</code>)</td><td>Re-run with the application that owns the release</td></tr></tbody></table><h2 id="the-invitation-page-says-the-link-is-invalid" tabindex="-1">The invitation page says the link is invalid <a class="header-anchor" href="#the-invitation-page-says-the-link-is-invalid" aria-label="Permalink to &quot;The invitation page says the link is invalid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;Open the link from your email&quot; on the join page</td><td>Link expired (seven days) or already used — links are single-use</td><td>Ask your team for a fresh invitation (<a href="/shipperdog/snapshot/how-to/portal/accept-invite">accept an invitation</a>)</td></tr><tr><td>Fresh link still refuses</td><td>The email you typed on the join card differs from the invited address</td><td>Use exactly the address the invitation was sent to</td></tr></tbody></table><h2 id="sso-login-does-not-complete" tabindex="-1">SSO login does not complete <a class="header-anchor" href="#sso-login-does-not-complete" aria-label="Permalink to &quot;SSO login does not complete&quot;">​</a></h2><p>The redirect leaves the IdP and lands nowhere useful — one of the handshake facts disagrees between the IdP and the organization&#39;s IdP configuration (<a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">configure SSO</a>).</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>IdP shows an error before redirecting</td><td>Client ID or redirect URI mismatch on the IdP application</td><td>Copy the console&#39;s SP metadata into the IdP app exactly</td></tr><tr><td>Redirect lands on an error page</td><td>Issuer URL typo, or <code>enabled</code> is still <code>false</code></td><td>Re-check <code>issuerUrl</code> against the IdP&#39;s real issuer; enable the record when tested</td></tr><tr><td>One user&#39;s login lands in the Console, another&#39;s bounces back to sign-in with an SSO error</td><td>Provisioning posture: <code>INVITED_ONLY</code> admits members only — and every SSO refusal, whatever its cause, answers the same uniform bounce (the distinct reason rides the audit line)</td><td>Add the member first, or switch to <code>JIT</code> deliberately (its default role is the VIEWER floor)</td></tr><tr><td>Group role mappings never apply</td><td><code>groupClaimName</code> does not match the token&#39;s claim</td><td>Name the claim exactly as the IdP issues it</td></tr></tbody></table><h2 id="scim-answers-401-to-everything" tabindex="-1">SCIM answers 401 to everything <a class="header-anchor" href="#scim-answers-401-to-everything" aria-label="Permalink to &quot;SCIM answers 401 to everything&quot;">​</a></h2><p>The SCIM surface&#39;s 401 is <strong>uniform by design</strong> — no response ever hints which leg refused, so the fix is a checklist, not a probe (<a href="/shipperdog/snapshot/how-to/console/scim-provisioning">configure SCIM</a>).</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Every push from the IdP gets 401</td><td>The connector token in the IdP differs from the one in ShipperDog&#39;s SCIM config</td><td>Re-copy the token, or rotate it in the console and update the IdP</td></tr><tr><td>Worked yesterday, 401 today</td><td>The token was rotated on one side only</td><td>Re-sync both sides</td></tr><tr><td>Need to know which leg refused</td><td>The distinct reason rides the audit line, never the response</td><td>An administrator reads the SCIM audit entries</td></tr></tbody></table><h2 id="webhook-deliveries-all-fail-401-—-or-one-hits-413" tabindex="-1">Webhook deliveries all fail 401 — or one hits 413 <a class="header-anchor" href="#webhook-deliveries-all-fail-401-—-or-one-hits-413" aria-label="Permalink to &quot;Webhook deliveries all fail 401 — or one hits 413&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Every delivery from GitHub/Jenkins/GitLab answers 401 <code>WEBHOOK_SIGNATURE_REJECTED</code></td><td>The shared secret differs between sender and receiver, or no secret is configured at the receiver</td><td>Set the identical secret on both sides (<a href="/shipperdog/snapshot/how-to/automation/webhooks">inbound webhooks</a>)</td></tr><tr><td>Sporadic 401s from the same sender</td><td>Stale-timestamp replay defense: the sender&#39;s clock drifts outside the window</td><td>Fix the sender&#39;s clock skew</td></tr><tr><td>Store deliveries (App Store/Play) answer 400 <code>WEBHOOK_DELIVERY_REJECTED</code></td><td>Provider token/audience verification failed</td><td>Re-check the provider&#39;s signed-configuration on the receiver</td></tr><tr><td>A delivery answers 413 <code>WEBHOOK_PAYLOAD_TOO_LARGE</code></td><td>Body over the payload ceiling (default 25 MB)</td><td>The provider must stay under the ceiling — GitHub&#39;s own cap matches</td></tr></tbody></table><h2 id="a-gate-is-stuck-no-data-yet-fail-closed" tabindex="-1">A gate is stuck &quot;no data yet (fail-closed)&quot; <a class="header-anchor" href="#a-gate-is-stuck-no-data-yet-fail-closed" aria-label="Permalink to &quot;A gate is stuck &quot;no data yet (fail-closed)&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Required gate blocks with no result ever recorded</td><td>No result submitted — the gate needs a pass/fail with a mandatory evidence URL from your pipeline</td><td>Submit it from CI: <code>shipperdog gate result R-… &lt;type&gt; --status pass --evidence-url …</code></td></tr><tr><td>Metric-backed gate (<code>crash-free-threshold</code>, <code>open-critical-bugs</code>) has no value</td><td>It resolves from analytics, not submissions — missing feeds leave it fail-closed</td><td>Let the analytics feed land, or <a href="/shipperdog/snapshot/how-to/console/quality-gates#override-a-blocking-gate">override once with an audited reason</a></td></tr><tr><td><code>open-critical-bugs</code> stays red</td><td>Feedback reports sit untriaged — the gate reads the live feedback block</td><td><a href="/shipperdog/snapshot/how-to/console/feedback-triage">Triage the reports</a>; the next evaluation re-reads</td></tr></tbody></table><h2 id="the-download-link-expired-mid-install" tabindex="-1">The download link expired mid-install <a class="header-anchor" href="#the-download-link-expired-mid-install" aria-label="Permalink to &quot;The download link expired mid-install&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;Link expired&quot; moments after tapping Download</td><td>Signed URLs live minutes by design; the pause took too long</td><td>Tap Download again — a fresh URL is minted per request</td></tr><tr><td>Fresh links also refuse, &quot;build not available&quot;</td><td>The release was rolled back or the grant revoked while you were installing</td><td>That is distribution being cut, not a bug — the team decides what re-opens access (<a href="/shipperdog/snapshot/how-to/console/rollback">rollback</a>)</td></tr></tbody></table><h2 id="promotion-answers-409-with-a-blocker-list" tabindex="-1">Promotion answers 409 with a blocker list <a class="header-anchor" href="#promotion-answers-409-with-a-blocker-list" aria-label="Permalink to &quot;Promotion answers 409 with a blocker list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>RELEASE_PROMOTION_BLOCKED</code> with gates/approvals/eligibility named</td><td>The target ring&#39;s evaluation refused the hop — every blocker is listed with evidence</td><td>Run <code>shipperdog release precheck &lt;id&gt;</code>; fix each named blocker, promote again (<a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">promote through rings</a>)</td></tr><tr><td><code>RELEASE_PROMOTION_RING_SKIP</code></td><td>The hop tried to jump a ring — one ring at a time is the default</td><td>Promote to the next ring; skips only if your organization explicitly allowed them</td></tr><tr><td><code>RELEASE_PROMOTION_RING_SPLIT</code></td><td>The selected targets sit on different rings (a prior selective promotion split them)</td><td>Promote ring group by ring group</td></tr><tr><td><code>RELEASE_PROMOTION_CONFLICT</code></td><td>A concurrent promotion moved the targets first</td><td>Re-read the release and retry — nothing partial committed</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">When reporting anything</p><p>Quote the <strong>trace id</strong> from the toast or the CLI output. It joins your failure to the exact server-side events — the difference between a ticket and an answer.</p></div>',26)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
